-- Feed multisource -> tab Multisource, base year 2026. Generated by scripts/it-handover.mjs; do not edit.
-- Column 1 is ROW_KEY (unique; drop it from the data file). The other columns are in sheet order.
-- Multisource: one row per cluster; demand = sum over that cluster's own usable members only. Demand columns come from the DEMAND template, one per demand year.
WITH MEMBER_DEMAND AS (
  SELECT
    M.MULTISOURCE_ID
    , SUM(IFF(K.IS_SOURCED_BY_US AND K.DEMAND_YEAR = 2025, K.TOTAL_DEMAND, 0)) AS DEMAND_2025
, SUM(IFF(K.IS_SOURCED_BY_US AND K.DEMAND_YEAR = 2026, K.TOTAL_DEMAND, 0)) AS DEMAND_2026
, SUM(IFF(K.IS_SOURCED_BY_US AND K.DEMAND_YEAR = 2027, K.TOTAL_DEMAND, 0)) AS DEMAND_2027
, SUM(IFF(K.IS_SOURCED_BY_US AND K.DEMAND_YEAR = 2028, K.TOTAL_DEMAND, 0)) AS DEMAND_2028
, SUM(IFF(K.IS_SOURCED_BY_US AND K.DEMAND_YEAR = 2029, K.TOTAL_DEMAND, 0)) AS DEMAND_2029
, SUM(IFF(K.IS_SOURCED_BY_US AND K.DEMAND_YEAR = 2030, K.TOTAL_DEMAND, 0)) AS DEMAND_2030
, SUM(IFF(K.IS_SOURCED_BY_US AND K.DEMAND_YEAR = 2031, K.TOTAL_DEMAND, 0)) AS DEMAND_2031
, SUM(IFF(K.IS_SOURCED_BY_US AND K.DEMAND_YEAR = 2032, K.TOTAL_DEMAND, 0)) AS DEMAND_2032
, SUM(IFF(K.IS_SOURCED_BY_US AND K.DEMAND_YEAR = 2033, K.TOTAL_DEMAND, 0)) AS DEMAND_2033
, SUM(IFF(K.IS_SOURCED_BY_US AND K.DEMAND_YEAR = 2034, K.TOTAL_DEMAND, 0)) AS DEMAND_2034
, SUM(IFF(K.IS_SOURCED_BY_US AND K.DEMAND_YEAR = 2035, K.TOTAL_DEMAND, 0)) AS DEMAND_2035
, SUM(IFF(K.IS_SOURCED_BY_US AND K.DEMAND_YEAR = 2036, K.TOTAL_DEMAND, 0)) AS DEMAND_2036
  FROM MECL_PLATFORM.ANALYTICS.MULTISOURCE_PART_MEMBERS M
  JOIN MECL_PLATFORM.ANALYTICS.KPI_COMPONENT_DEMAND_BY_YEAR K
    ON K.PART_ID = M.COMPONENT_ID AND K.PART_KIND = 'COMPONENT'
  WHERE M.IS_USABLE
  GROUP BY M.MULTISOURCE_ID
)
SELECT
  P.MS_PART_NUMBER AS ROW_KEY,
  P.MS_PART_NUMBER AS ME_MS,
  P.SOURCING_HEALTH AS SOURCING_HEALTH,
  P.MEMBER_COUNT AS MEMBER_COUNT,
  P.USABLE_MEMBERS AS USABLE_MEMBER_COUNT,
  P.MANUFACTURER_COUNT AS MANUFACTURER_COUNT
  , COALESCE(D.DEMAND_2025, 0) AS DEMAND_2025
, COALESCE(D.DEMAND_2026, 0) AS DEMAND_2026
, COALESCE(D.DEMAND_2027, 0) AS DEMAND_2027
, COALESCE(D.DEMAND_2028, 0) AS DEMAND_2028
, COALESCE(D.DEMAND_2029, 0) AS DEMAND_2029
, COALESCE(D.DEMAND_2030, 0) AS DEMAND_2030
, COALESCE(D.DEMAND_2031, 0) AS DEMAND_2031
, COALESCE(D.DEMAND_2032, 0) AS DEMAND_2032
, COALESCE(D.DEMAND_2033, 0) AS DEMAND_2033
, COALESCE(D.DEMAND_2034, 0) AS DEMAND_2034
, COALESCE(D.DEMAND_2035, 0) AS DEMAND_2035
, COALESCE(D.DEMAND_2036, 0) AS DEMAND_2036
FROM MECL_PLATFORM.ANALYTICS.MULTISOURCE_PARTS P
LEFT JOIN MEMBER_DEMAND D ON D.MULTISOURCE_ID = P.MULTISOURCE_ID
ORDER BY ROW_KEY;
